    {
        int count = 0;
        int index1 = 0;
        int index2 = 0;
        while (index1 < array1.Length && index2 < array2.Length)
        {
            if (array1[index1] == array2[index2])
            {
                count++;
                index1++;
                index2++;
            }
            else
